  'Kasr v1: 8 home sections, Studio, Contact, FAQ pages'
FROM templates t
WHERE t.key = 'kasr'
ON CONFLICT (template_id, version) DO NOTHING;

UPDATE templates t SET current_version_id = v.id, updated_at = now()
FROM template_versions v
WHERE t.key = 'kasr' AND v.template_id = t.id AND v.version = 1
  AND t.current_version_id IS DISTINCT FROM v.id;

-- Rollback: DELETE FROM templates WHERE key = 'kasr'; (cascades to its versions and installs).
